using System.Text;
using System.Text.Json;
using Dapper;
using Microsoft.Extensions.Logging;
using Npgsql;
using Sigov.Application.Almoxarifado;
using Sigov.Infrastructure.Persistence.Dapper;

namespace Sigov.Infrastructure.Almoxarifado;

public sealed class AlmoxarifadoService(NpgsqlConnectionFactory factory,Microsoft.Extensions.Logging.ILogger<AlmoxarifadoService> logger):IAlmoxarifadoService
{
 public async Task<AlmoxarifadoDashboard> ObterDashboardAsync(long t,long e,CancellationToken ct){await using var c=factory.CreateConnection();var x=await c.QuerySingleAsync<Resumo>(new CommandDefinition("select (select count(*) from sigov.almoxarifado_material where tenant_id=@T and entidade_id=@E and ativo) Materiais,(select count(*) from sigov.almoxarifado_estoque s join sigov.almoxarifado_material m on m.id=s.material_id and m.tenant_id=s.tenant_id where s.tenant_id=@T and s.entidade_id=@E and s.quantidade<m.estoque_minimo) Baixos,(select count(*) from sigov.almoxarifado_requisicao where tenant_id=@T and entidade_id=@E and status in ('ENVIADA','APROVADA')) Pendentes,(select count(*) from sigov.almoxarifado_movimentacao where tenant_id=@T and entidade_id=@E and tipo='ENTRADA' and ocorrido_em>=date_trunc('month',now())) Entradas,(select count(*) from sigov.almoxarifado_movimentacao where tenant_id=@T and entidade_id=@E and tipo='SAIDA' and ocorrido_em>=date_trunc('month',now())) Saidas,(select count(*) from sigov.almoxarifado_pendencia_patrimonial where tenant_id=@T and entidade_id=@E and status='PENDENTE') Pendencias",new{T=t,E=e},cancellationToken:ct));var mov=(await c.QueryAsync<MovimentacaoDto>(new CommandDefinition(MovSql+" order by x.ocorrido_em desc limit 10",new{T=t,E=e},cancellationToken:ct))).AsList();var baixo=(await c.QueryAsync<BaixoEstoqueDto>(new CommandDefinition("select m.codigo MaterialCodigo,m.descricao MaterialDescricao,l.nome LocalNome,s.quantidade,m.estoque_minimo EstoqueMinimo from sigov.almoxarifado_estoque s join sigov.almoxarifado_material m on m.id=s.material_id and m.tenant_id=s.tenant_id join sigov.almoxarifado_local l on l.id=s.almoxarifado_id and l.tenant_id=s.tenant_id where s.tenant_id=@T and s.entidade_id=@E and s.quantidade<m.estoque_minimo order by (m.estoque_minimo-s.quantidade) desc limit 10",new{T=t,E=e},cancellationToken:ct))).AsList();return new(x.Materiais,x.Baixos,x.Pendentes,x.Entradas,x.Saidas,x.Pendencias,mov,baixo);}
 public async Task<AlmoxarifadoPagina<MaterialDto>> ListarMateriaisAsync(long t,long e,AlmoxarifadoFiltro f,CancellationToken ct){var p=Math.Max(f.Pagina,1);var z=Math.Clamp(f.TamanhoPagina,1,100);const string w="tenant_id=@T and entidade_id=@E and (@B is null or codigo ilike '%'||@B||'%' or descricao ilike '%'||@B||'%') and (@A is null or ativo=@A)";var a=new{T=t,E=e,B=N(f.Busca),A=f.Ativo,L=z,O=(p-1)*z};await using var c=factory.CreateConnection();var total=await c.ExecuteScalarAsync<long>(new CommandDefinition($"select count(*) from sigov.almoxarifado_material where {w}",a,cancellationToken:ct));var rows=(await c.QueryAsync<MaterialDto>(new CommandDefinition($"select id,entidade_id EntidadeId,codigo,descricao,tipo_material TipoMaterial,unidade_medida UnidadeMedida,categoria,estoque_minimo EstoqueMinimo,estoque_maximo EstoqueMaximo,controla_lote ControlaLote,controla_validade ControlaValidade,ativo,created_at CreatedAt,updated_at UpdatedAt from sigov.almoxarifado_material where {w} order by descricao limit @L offset @O",a,cancellationToken:ct))).AsList();return new(rows,p,z,total);}
 public async Task<MaterialDto?> ObterMaterialAsync(long t,long e,long id,CancellationToken ct){await using var c=factory.CreateConnection();return await c.QuerySingleOrDefaultAsync<MaterialDto>(new CommandDefinition("select id,entidade_id EntidadeId,codigo,descricao,tipo_material TipoMaterial,unidade_medida UnidadeMedida,categoria,estoque_minimo EstoqueMinimo,estoque_maximo EstoqueMaximo,controla_lote ControlaLote,controla_validade ControlaValidade,ativo,created_at CreatedAt,updated_at UpdatedAt from sigov.almoxarifado_material where tenant_id=@T and entidade_id=@E and id=@Id",new{T=t,E=e,Id=id},cancellationToken:ct));}
 public async Task<long> CriarMaterialAsync(long t,long u,string corr,MaterialInput i,CancellationToken ct){Validar(i);await using var c=factory.CreateConnection();await c.OpenAsync(ct);await using var tx=await c.BeginTransactionAsync(ct);try{var id=await c.ExecuteScalarAsync<long>(new CommandDefinition("insert into sigov.almoxarifado_material(tenant_id,entidade_id,codigo,descricao,tipo_material,unidade_medida,categoria,estoque_minimo,estoque_maximo,controla_lote,controla_validade,ativo,created_by,updated_by) values(@T,@EntidadeId,@Codigo,@Descricao,@TipoMaterial,@UnidadeMedida,@Categoria,@EstoqueMinimo,@EstoqueMaximo,@ControlaLote,@ControlaValidade,@Ativo,@U,@U) returning id",Args(i,t,u),tx,cancellationToken:ct));await Audit(c,tx,t,i.EntidadeId,"MATERIAL",id,"CRIAR",null,i,u,corr,ct);await tx.CommitAsync(ct);return id;}catch(PostgresException x)when(x.SqlState==PostgresErrorCodes.UniqueViolation){await tx.RollbackAsync(ct);throw new InvalidOperationException("Código de material já existe para a entidade.",x);}}
 public async Task EditarMaterialAsync(long t,long u,string corr,long id,MaterialInput i,CancellationToken ct){Validar(i);await using var c=factory.CreateConnection();await c.OpenAsync(ct);await using var tx=await c.BeginTransactionAsync(ct);var antes=await Json(c,tx,t,i.EntidadeId,id,ct)??throw new KeyNotFoundException("Material não encontrado.");try{var parameters=new DynamicParameters(Args(i,t,u));parameters.Add("Id",id);var n=await c.ExecuteAsync(new CommandDefinition("update sigov.almoxarifado_material set codigo=@Codigo,descricao=@Descricao,tipo_material=@TipoMaterial,unidade_medida=@UnidadeMedida,categoria=@Categoria,estoque_minimo=@EstoqueMinimo,estoque_maximo=@EstoqueMaximo,controla_lote=@ControlaLote,controla_validade=@ControlaValidade,ativo=@Ativo,updated_at=now(),updated_by=@U where tenant_id=@T and entidade_id=@EntidadeId and id=@Id",parameters,tx,cancellationToken:ct));if(n==0)throw new KeyNotFoundException("Material não encontrado.");await Audit(c,tx,t,i.EntidadeId,"MATERIAL",id,"EDITAR",antes,i,u,corr,ct);await tx.CommitAsync(ct);}catch(PostgresException x)when(x.SqlState==PostgresErrorCodes.UniqueViolation){await tx.RollbackAsync(ct);throw new InvalidOperationException("Código de material já existe para a entidade.",x);}}
 public async Task<IReadOnlyList<LocalDto>> ListarLocaisAsync(long t,long e,bool? ativo,CancellationToken ct){await using var c=factory.CreateConnection();return(await c.QueryAsync<LocalDto>(new CommandDefinition("select id,entidade_id EntidadeId,unidade_id UnidadeId,codigo,nome,responsavel_nome ResponsavelNome,ativo from sigov.almoxarifado_local where tenant_id=@T and entidade_id=@E and (@A is null or ativo=@A) order by nome",new{T=t,E=e,A=ativo},cancellationToken:ct))).AsList();}
 public async Task<long> CriarLocalAsync(long t,long u,string corr,LocalInput i,CancellationToken ct){if(string.IsNullOrWhiteSpace(i.Codigo)||string.IsNullOrWhiteSpace(i.Nome))throw new ArgumentException("Código e nome do local são obrigatórios.");await using var c=factory.CreateConnection();var id=await c.ExecuteScalarAsync<long>(new CommandDefinition("insert into sigov.almoxarifado_local(tenant_id,entidade_id,unidade_id,codigo,nome,responsavel_nome,ativo,created_by,updated_by) values(@T,@EntidadeId,@UnidadeId,@Codigo,@Nome,@ResponsavelNome,@Ativo,@U,@U) returning id",new{T=t,U=u,i.EntidadeId,i.UnidadeId,Codigo=i.Codigo.Trim(),Nome=i.Nome.Trim(),ResponsavelNome=N(i.ResponsavelNome),i.Ativo},cancellationToken:ct));return id;}
 public async Task<IReadOnlyList<EstoqueDto>> ListarEstoqueAsync(long t,long e,string? busca,CancellationToken ct){await using var c=factory.CreateConnection();return(await c.QueryAsync<EstoqueDto>(new CommandDefinition("select l.id LocalId,l.codigo LocalCodigo,l.nome LocalNome,m.id MaterialId,m.codigo MaterialCodigo,m.descricao MaterialDescricao,m.unidade_medida UnidadeMedida,s.quantidade,m.estoque_minimo EstoqueMinimo,(s.quantidade<m.estoque_minimo) AbaixoMinimo from sigov.almoxarifado_estoque s join sigov.almoxarifado_local l on l.id=s.almoxarifado_id and l.tenant_id=s.tenant_id join sigov.almoxarifado_material m on m.id=s.material_id and m.tenant_id=s.tenant_id where s.tenant_id=@T and s.entidade_id=@E and (@B is null or m.codigo ilike '%'||@B||'%' or m.descricao ilike '%'||@B||'%' or l.nome ilike '%'||@B||'%') order by m.descricao,l.nome",new{T=t,E=e,B=N(busca)},cancellationToken:ct))).AsList();}
 public Task RegistrarEntradaAsync(long t,long u,string corr,MovimentacaoInput i,CancellationToken ct)=>Movimentar(t,u,corr,i,true,ct); public Task RegistrarSaidaAsync(long t,long u,string corr,MovimentacaoInput i,CancellationToken ct)=>Movimentar(t,u,corr,i,false,ct);
 async Task Movimentar(long t,long u,string corr,MovimentacaoInput i,bool entrada,CancellationToken ct){if(i.Quantidade<=0)throw new ArgumentException("Quantidade deve ser maior que zero.");await using var c=factory.CreateConnection();await c.OpenAsync(ct);await using var tx=await c.BeginTransactionAsync(ct);var mat=await c.QuerySingleOrDefaultAsync<Mat>(new CommandDefinition("select tipo_material Tipo from sigov.almoxarifado_material where tenant_id=@T and entidade_id=@E and id=@M and ativo for update",new{T=t,E=i.EntidadeId,M=i.MaterialId},tx,cancellationToken:ct))??throw new KeyNotFoundException("Material ativo não encontrado.");var local=await c.ExecuteScalarAsync<long?>(new CommandDefinition("select id from sigov.almoxarifado_local where tenant_id=@T and entidade_id=@E and id=@L and ativo",new{T=t,E=i.EntidadeId,L=i.AlmoxarifadoId},tx,cancellationToken:ct));if(local is null)throw new KeyNotFoundException("Almoxarifado ativo não encontrado.");await c.ExecuteAsync(new CommandDefinition("insert into sigov.almoxarifado_estoque(tenant_id,entidade_id,almoxarifado_id,material_id,quantidade) values(@T,@E,@L,@M,0) on conflict(tenant_id,entidade_id,almoxarifado_id,material_id) do nothing",new{T=t,E=i.EntidadeId,L=i.AlmoxarifadoId,M=i.MaterialId},tx,cancellationToken:ct));var antes=await c.ExecuteScalarAsync<decimal>(new CommandDefinition("select quantidade from sigov.almoxarifado_estoque where tenant_id=@T and entidade_id=@E and almoxarifado_id=@L and material_id=@M for update",new{T=t,E=i.EntidadeId,L=i.AlmoxarifadoId,M=i.MaterialId},tx,cancellationToken:ct));var depois=entrada?antes+i.Quantidade:antes-i.Quantidade;if(depois<0)throw new InvalidOperationException($"Saldo insuficiente. Disponível: {antes}.");await c.ExecuteAsync(new CommandDefinition("update sigov.almoxarifado_estoque set quantidade=@Q,updated_at=now() where tenant_id=@T and entidade_id=@E and almoxarifado_id=@L and material_id=@M",new{Q=depois,T=t,E=i.EntidadeId,L=i.AlmoxarifadoId,M=i.MaterialId},tx,cancellationToken:ct));var mov=await c.ExecuteScalarAsync<long>(new CommandDefinition("insert into sigov.almoxarifado_movimentacao(tenant_id,entidade_id,almoxarifado_id,material_id,tipo,motivo,quantidade,valor_unitario,lote,validade,documento_origem,observacao,saldo_antes,saldo_depois,usuario_id,correlation_id) values(@T,@E,@L,@M,@Tipo,@Motivo,@Q,@Valor,@Lote,@Validade,@Doc,@Obs,@Antes,@Depois,@U,@Corr) returning id",new{T=t,E=i.EntidadeId,L=i.AlmoxarifadoId,M=i.MaterialId,Tipo=entrada?"ENTRADA":"SAIDA",Motivo=i.Tipo,Q=i.Quantidade,Valor=i.ValorUnitario,Lote=N(i.Lote),Validade=i.Validade,Doc=N(i.DocumentoOrigem),Obs=N(i.Observacao),Antes=antes,Depois=depois,U=u,Corr=corr},tx,cancellationToken:ct));if(entrada&&mat.Tipo=="PERMANENTE")await c.ExecuteAsync(new CommandDefinition("insert into sigov.almoxarifado_pendencia_patrimonial(tenant_id,entidade_id,movimentacao_id,material_id,quantidade,status) values(@T,@E,@Mov,@M,@Q,'PENDENTE') on conflict(movimentacao_id) do nothing",new{T=t,E=i.EntidadeId,Mov=mov,M=i.MaterialId,Q=i.Quantidade},tx,cancellationToken:ct));await Audit(c,tx,t,i.EntidadeId,"MOVIMENTACAO",mov,entrada?"ENTRADA":"SAIDA",new{Saldo=antes},new{Saldo=depois,i.Quantidade},u,corr,ct);await tx.CommitAsync(ct);logger.LogInformation("Movimentação {MovimentacaoId} {Tipo} registrada para tenant {TenantId} e entidade {EntidadeId}",mov,entrada?"ENTRADA":"SAIDA",t,i.EntidadeId);}
 public async Task<AlmoxarifadoPagina<RequisicaoDto>> ListarRequisicoesAsync(long t,long e,string? status,int pagina,CancellationToken ct){pagina=Math.Max(1,pagina);await using var c=factory.CreateConnection();var a=new{T=t,E=e,S=N(status),O=(pagina-1)*25};var total=await c.ExecuteScalarAsync<long>(new CommandDefinition("select count(*) from sigov.almoxarifado_requisicao where tenant_id=@T and entidade_id=@E and (@S is null or status=@S)",a,cancellationToken:ct));var rows=(await c.QueryAsync<RequisicaoDto>(new CommandDefinition(ReqSql+" and (@S is null or r.status=@S) group by r.id,l.nome order by r.created_at desc limit 25 offset @O",a,cancellationToken:ct))).AsList();return new(rows,pagina,25,total);}
 public async Task<RequisicaoDetalhe?> ObterRequisicaoAsync(long t,long e,long id,CancellationToken ct){await using var c=factory.CreateConnection();var r=await c.QuerySingleOrDefaultAsync<RequisicaoDto>(new CommandDefinition(ReqSql+" and r.id=@Id group by r.id,l.nome",new{T=t,E=e,Id=id},cancellationToken:ct));if(r is null)return null;var itens=(await c.QueryAsync<RequisicaoItemDto>(new CommandDefinition("select i.id,i.material_id MaterialId,m.codigo,m.descricao,m.unidade_medida UnidadeMedida,i.quantidade_solicitada QuantidadeSolicitada,i.quantidade_atendida QuantidadeAtendida from sigov.almoxarifado_requisicao_item i join sigov.almoxarifado_material m on m.id=i.material_id and m.tenant_id=i.tenant_id where i.tenant_id=@T and i.entidade_id=@E and i.requisicao_id=@Id order by i.id",new{T=t,E=e,Id=id},cancellationToken:ct))).AsList();var h=(await c.QueryAsync<RequisicaoHistoricoDto>(new CommandDefinition("select status_anterior StatusAnterior,status_novo StatusNovo,justificativa,ocorrido_em OcorridoEm from sigov.almoxarifado_requisicao_historico where tenant_id=@T and entidade_id=@E and requisicao_id=@Id order by ocorrido_em,id",new{T=t,E=e,Id=id},cancellationToken:ct))).AsList();return new(r,itens,h);}
 public async Task<long> CriarRequisicaoAsync(long t,long u,string corr,RequisicaoInput i,CancellationToken ct){if(i.Itens is null||i.Itens.Count==0||i.Itens.Any(x=>x.QuantidadeSolicitada<=0))throw new ArgumentException("Informe ao menos um item com quantidade positiva.");await using var c=factory.CreateConnection();await c.OpenAsync(ct);await using var tx=await c.BeginTransactionAsync(ct);var id=await c.ExecuteScalarAsync<long>(new CommandDefinition("insert into sigov.almoxarifado_requisicao(tenant_id,entidade_id,almoxarifado_id,unidade_solicitante_id,status,observacao,created_by,updated_by) select @T,@E,@L,@Unidade,'RASCUNHO',@Obs,@U,@U where exists(select 1 from sigov.almoxarifado_local where tenant_id=@T and entidade_id=@E and id=@L and ativo) returning id",new{T=t,E=i.EntidadeId,L=i.AlmoxarifadoId,Unidade=i.UnidadeSolicitanteId,Obs=N(i.Observacao),U=u},tx,cancellationToken:ct));foreach(var item in i.Itens)await c.ExecuteAsync(new CommandDefinition("insert into sigov.almoxarifado_requisicao_item(tenant_id,entidade_id,requisicao_id,material_id,quantidade_solicitada) select @T,@E,@R,@M,@Q where exists(select 1 from sigov.almoxarifado_material where tenant_id=@T and entidade_id=@E and id=@M and ativo)",new{T=t,E=i.EntidadeId,R=id,M=item.MaterialId,Q=item.QuantidadeSolicitada},tx,cancellationToken:ct));await Historico(c,tx,t,i.EntidadeId,id,"","RASCUNHO",null,u,corr,ct);await tx.CommitAsync(ct);return id;}
 public async Task AlterarStatusAsync(long t,long e,long u,string corr,long id,string acao,string? just,CancellationToken ct){acao=acao.ToUpperInvariant();await using var c=factory.CreateConnection();await c.OpenAsync(ct);await using var tx=await c.BeginTransactionAsync(ct);var r=await c.QuerySingleOrDefaultAsync<ReqEstado>(new CommandDefinition("select status,almoxarifado_id LocalId from sigov.almoxarifado_requisicao where tenant_id=@T and entidade_id=@E and id=@Id for update",new{T=t,E=e,Id=id},tx,cancellationToken:ct))??throw new KeyNotFoundException("Requisição não encontrada.");var novo=(r.Status,acao) switch{("RASCUNHO","ENVIAR")=>"ENVIADA",("ENVIADA","APROVAR")=>"APROVADA",("ENVIADA","REJEITAR")=>"REJEITADA",("APROVADA","ATENDER")=>"ATENDIDA",("RASCUNHO" or "ENVIADA","CANCELAR")=>"CANCELADA",_=>throw new InvalidOperationException($"Ação {acao} não permitida no status {r.Status}.")};if((acao is "REJEITAR" or "CANCELAR")&&string.IsNullOrWhiteSpace(just))throw new ArgumentException("Justificativa é obrigatória.");if(acao=="ATENDER"){var itens=(await c.QueryAsync<ItemAtender>(new CommandDefinition("select material_id MaterialId,quantidade_solicitada Quantidade from sigov.almoxarifado_requisicao_item where tenant_id=@T and entidade_id=@E and requisicao_id=@Id order by id",new{T=t,E=e,Id=id},tx,cancellationToken:ct))).AsList();foreach(var item in itens){var input=new MovimentacaoInput(e,r.LocalId,item.MaterialId,item.Quantidade,"REQUISICAO",id.ToString(),$"Atendimento da requisição {id}");await SaidaTx(c,tx,t,u,corr,input,id,ct);await c.ExecuteAsync(new CommandDefinition("update sigov.almoxarifado_requisicao_item set quantidade_atendida=quantidade_solicitada where tenant_id=@T and entidade_id=@E and requisicao_id=@R and material_id=@M",new{T=t,E=e,R=id,M=item.MaterialId},tx,cancellationToken:ct));}}await c.ExecuteAsync(new CommandDefinition("update sigov.almoxarifado_requisicao set status=@S,justificativa=@J,updated_at=now(),updated_by=@U where tenant_id=@T and entidade_id=@E and id=@Id",new{S=novo,J=N(just),U=u,T=t,E=e,Id=id},tx,cancellationToken:ct));await Historico(c,tx,t,e,id,r.Status,novo,N(just),u,corr,ct);await tx.CommitAsync(ct);}
 async Task SaidaTx(NpgsqlConnection c,NpgsqlTransaction tx,long t,long u,string corr,MovimentacaoInput i,long req,CancellationToken ct){var saldo=await c.ExecuteScalarAsync<decimal?>(new CommandDefinition("select quantidade from sigov.almoxarifado_estoque where tenant_id=@T and entidade_id=@E and almoxarifado_id=@L and material_id=@M for update",new{T=t,E=i.EntidadeId,L=i.AlmoxarifadoId,M=i.MaterialId},tx,cancellationToken:ct))??0;if(saldo<i.Quantidade)throw new InvalidOperationException($"Saldo insuficiente para o material {i.MaterialId}. Disponível: {saldo}.");await c.ExecuteAsync(new CommandDefinition("update sigov.almoxarifado_estoque set quantidade=quantidade-@Q,updated_at=now() where tenant_id=@T and entidade_id=@E and almoxarifado_id=@L and material_id=@M",new{Q=i.Quantidade,T=t,E=i.EntidadeId,L=i.AlmoxarifadoId,M=i.MaterialId},tx,cancellationToken:ct));await c.ExecuteAsync(new CommandDefinition("insert into sigov.almoxarifado_movimentacao(tenant_id,entidade_id,almoxarifado_id,material_id,requisicao_id,tipo,motivo,quantidade,documento_origem,observacao,saldo_antes,saldo_depois,usuario_id,correlation_id) values(@T,@E,@L,@M,@R,'SAIDA','REQUISICAO',@Q,@Doc,@Obs,@Antes,@Depois,@U,@Corr)",new{T=t,E=i.EntidadeId,L=i.AlmoxarifadoId,M=i.MaterialId,R=req,Q=i.Quantidade,Doc=i.DocumentoOrigem,Obs=i.Observacao,Antes=saldo,Depois=saldo-i.Quantidade,U=u,Corr=corr},tx,cancellationToken:ct));}
 public async Task<byte[]> ExportarCsvAsync(long t,long e,string tipo,long u,string corr,CancellationToken ct){await using var c=factory.CreateConnection();IEnumerable<dynamic> rows;string header;if(tipo=="saldo"){rows=await c.QueryAsync(new CommandDefinition("select m.codigo,m.descricao,l.nome local,s.quantidade,m.unidade_medida from sigov.almoxarifado_estoque s join sigov.almoxarifado_material m on m.id=s.material_id and m.tenant_id=s.tenant_id join sigov.almoxarifado_local l on l.id=s.almoxarifado_id and l.tenant_id=s.tenant_id where s.tenant_id=@T and s.entidade_id=@E order by m.codigo limit 5000",new{T=t,E=e},cancellationToken:ct));header="Código;Descrição;Local;Quantidade;Unidade\r\n";}else if(tipo=="movimentacoes"){rows=await c.QueryAsync(new CommandDefinition("select m.codigo,x.tipo,x.motivo,x.quantidade,x.saldo_antes,x.saldo_depois,x.ocorrido_em from sigov.almoxarifado_movimentacao x join sigov.almoxarifado_material m on m.id=x.material_id and m.tenant_id=x.tenant_id where x.tenant_id=@T and x.entidade_id=@E order by x.ocorrido_em desc limit 5000",new{T=t,E=e},cancellationToken:ct));header="Código;Tipo;Motivo;Quantidade;Saldo antes;Saldo depois;Data\r\n";}else{rows=await c.QueryAsync(new CommandDefinition("select codigo,descricao,tipo_material,unidade_medida,categoria,ativo from sigov.almoxarifado_material where tenant_id=@T and entidade_id=@E order by codigo limit 5000",new{T=t,E=e},cancellationToken:ct));header="Código;Descrição;Tipo;Unidade;Categoria;Ativo\r\n";}var sb=new StringBuilder(header);foreach(var row in rows)sb.AppendLine(string.Join(';',((IDictionary<string,object>)row).Values.Select(v=>Csv(v?.ToString()))));await c.ExecuteAsync(new CommandDefinition("insert into sigov.almoxarifado_auditoria(tenant_id,entidade_id,entidade,registro_id,operacao,depois,usuario_id,correlation_id) values(@T,@E,'EXPORTACAO',0,'EXPORTAR',jsonb_build_object('tipo',@Tipo),@U,@Corr)",new{T=t,E=e,Tipo=tipo,U=u,Corr=corr},cancellationToken:ct));return new UTF8Encoding(true).GetBytes(sb.ToString());}
 static void Validar(MaterialInput i){if(i.EntidadeId<=0||string.IsNullOrWhiteSpace(i.Codigo)||string.IsNullOrWhiteSpace(i.Descricao)||string.IsNullOrWhiteSpace(i.UnidadeMedida))throw new ArgumentException("Entidade, código, descrição e unidade são obrigatórios.");if(i.TipoMaterial is not("CONSUMO" or "PERMANENTE"))throw new ArgumentException("Tipo de material inválido.");if(i.EstoqueMinimo<0||i.EstoqueMaximo<i.EstoqueMinimo)throw new ArgumentException("Estoque mínimo não pode ser negativo e máximo não pode ser menor que o mínimo.");}
 static object Args(MaterialInput i,long t,long u)=>new{T=t,U=u,i.EntidadeId,Codigo=i.Codigo.Trim(),Descricao=i.Descricao.Trim(),i.TipoMaterial,UnidadeMedida=i.UnidadeMedida.Trim(),Categoria=N(i.Categoria),i.EstoqueMinimo,i.EstoqueMaximo,i.ControlaLote,i.ControlaValidade,i.Ativo};
 static Task Audit(NpgsqlConnection c,NpgsqlTransaction tx,long t,long e,string ent,long id,string op,object? antes,object? depois,long u,string corr,CancellationToken ct)=>c.ExecuteAsync(new CommandDefinition("insert into sigov.almoxarifado_auditoria(tenant_id,entidade_id,entidade,registro_id,operacao,antes,depois,usuario_id,correlation_id) values(@T,@E,@Ent,@Id,@Op,cast(@Antes as jsonb),cast(@Depois as jsonb),@U,@Corr)",new{T=t,E=e,Ent=ent,Id=id,Op=op,Antes=antes is null?null:JsonSerializer.Serialize(antes),Depois=depois is null?null:JsonSerializer.Serialize(depois),U=u,Corr=corr},tx,cancellationToken:ct));
 static Task Historico(NpgsqlConnection c,NpgsqlTransaction tx,long t,long e,long id,string ant,string novo,string? just,long u,string corr,CancellationToken ct)=>c.ExecuteAsync(new CommandDefinition("insert into sigov.almoxarifado_requisicao_historico(tenant_id,entidade_id,requisicao_id,status_anterior,status_novo,justificativa,usuario_id,correlation_id) values(@T,@E,@Id,@Ant,@Novo,@Just,@U,@Corr)",new{T=t,E=e,Id=id,Ant=ant,Novo=novo,Just=just,U=u,Corr=corr},tx,cancellationToken:ct));
 static async Task<string?> Json(NpgsqlConnection c,NpgsqlTransaction tx,long t,long e,long id,CancellationToken ct)=>await c.ExecuteScalarAsync<string?>(new CommandDefinition("select to_jsonb(x)::text from sigov.almoxarifado_material x where tenant_id=@T and entidade_id=@E and id=@Id",new{T=t,E=e,Id=id},tx,cancellationToken:ct));
 static string? N(string? x)=>string.IsNullOrWhiteSpace(x)?null:x.Trim();static string Csv(string? x){x??="";if(x.Length>0&&"=+-@".Contains(x[0]))x="'"+x;return '"'+x.Replace("\"","\"\"")+'"';}
 const string MovSql="select x.id,x.tipo,x.motivo,m.codigo MaterialCodigo,m.descricao MaterialDescricao,l.nome LocalNome,x.quantidade,x.saldo_antes SaldoAntes,x.saldo_depois SaldoDepois,x.ocorrido_em OcorridoEm from sigov.almoxarifado_movimentacao x join sigov.almoxarifado_material m on m.id=x.material_id and m.tenant_id=x.tenant_id join sigov.almoxarifado_local l on l.id=x.almoxarifado_id and l.tenant_id=x.tenant_id where x.tenant_id=@T and x.entidade_id=@E";
 const string ReqSql="select r.id,r.entidade_id EntidadeId,r.almoxarifado_id AlmoxarifadoId,l.nome LocalNome,r.unidade_solicitante_id UnidadeSolicitanteId,r.status,r.observacao,r.justificativa,r.created_at CreatedAt,count(i.id)::int TotalItens from sigov.almoxarifado_requisicao r join sigov.almoxarifado_local l on l.id=r.almoxarifado_id and l.tenant_id=r.tenant_id left join sigov.almoxarifado_requisicao_item i on i.requisicao_id=r.id and i.tenant_id=r.tenant_id where r.tenant_id=@T and r.entidade_id=@E";
 sealed record Resumo(long Materiais,long Baixos,long Pendentes,long Entradas,long Saidas,long Pendencias);sealed record Mat(string Tipo);sealed record ReqEstado(string Status,long LocalId);sealed record ItemAtender(long MaterialId,decimal Quantidade);
